// План specs/rbac.md 2.1–2.2, 3.1 (тикет #04d338, реджект №1). PROD, компания «test», десктоп, EN. Две роли: владелец (admin) меняет роль Test Nikita,
// диспетчер (dispatcher) проверяет свой экран. @writes: временная смена роли → в finally возврат на Admin-dispatcher. DELETE-запросы в тесте идут
// БЕЗ права (ожидаем 403) — запись не удаляется; если вдруг 2xx — тест падает, но это значит дыру в правах (удалить QA-запись нечем, сообщить).
import { test, expect } from '../../fixtures';
import {
  DISPATCHER_NAME, ROLE_DISPATCHER, ROLE_OPS, authHeaders, expectHeaderRole, openFirstInvoiceActions, openTeam, prepare, setMemberRole, supabaseSession,
} from './rbac-helpers';

test.describe.configure({ mode: 'serial' });

test.describe('RBAC — Operations manager cannot delete invoices and payments (#04d338)', () => {
  test('QA-AUTO: Operations manager has no Delete in invoice Actions, and direct DELETE of Invoice / JobPayment returns 403 delete_forbidden #04d338 @desktop @writes', async ({ asUser }) => {
    test.setTimeout(180_000);
    const owner = await asUser('admin');
    await prepare(owner);
    let changed = false;
    try {
      await openTeam(owner);
      await setMemberRole(owner, DISPATCHER_NAME, ROLE_OPS);
      changed = true;

      // Диспетчер в новом окне (после смены роли): роль в шапке
      const ops = await asUser('dispatcher');
      await prepare(ops);
      await ops.goto('/dashboard');
      await expectHeaderRole(ops, DISPATCHER_NAME, ROLE_OPS);

      // 2.1: счёт → Actions — Delete нет (источник: карточка роли «Cannot delete invoices or payments», реджект №1)
      const invoiceId = await openFirstInvoiceActions(ops);
      await expect(ops.getByRole('menuitem', { name: /Delete/i })).toHaveCount(0);
      await ops.keyboard.press('Escape');

      // 2.2: прямой DELETE токеном этой сессии → 403, подсказка delete_forbidden, запись цела (DoD «פעולה ללא הרשאה … מחזירה 403»)
      const s = await supabaseSession(ops);
      const h = authHeaders(s);
      const delInv = await ops.request.delete(`${s.base}/rest/v1/Invoice?id=eq.${invoiceId}`, { headers: { ...h, Prefer: 'return=representation' } });
      expect(delInv.status(), 'DELETE /rest/v1/Invoice без права').toBe(403);
      expect(((await delInv.json().catch(() => ({}))) as { hint?: string }).hint, 'hint ошибки Invoice').toBe('delete_forbidden');
      const stillInv = await ops.request.get(`${s.base}/rest/v1/Invoice?select=id&id=eq.${invoiceId}`, { headers: h });
      expect(((await stillInv.json()) as unknown[]).length, 'счёт после отказа цел').toBe(1);

      const pay = await ops.request.get(`${s.base}/rest/v1/JobPayment?select=id&limit=1`, { headers: h });
      const [payment] = (await pay.json().catch(() => [])) as { id: string }[];
      if (payment?.id) {
        const delPay = await ops.request.delete(`${s.base}/rest/v1/JobPayment?id=eq.${payment.id}`, { headers: { ...h, Prefer: 'return=representation' } });
        expect(delPay.status(), 'DELETE /rest/v1/JobPayment без права').toBe(403);
        expect(((await delPay.json().catch(() => ({}))) as { hint?: string }).hint, 'hint ошибки JobPayment').toBe('delete_forbidden');
        const stillPay = await ops.request.get(`${s.base}/rest/v1/JobPayment?select=id&id=eq.${payment.id}`, { headers: h });
        expect(((await stillPay.json()) as unknown[]).length, 'платёж после отказа цел').toBe(1);
      } else {
        test.info().annotations.push({ type: 'note', description: 'В компании test нет платежей JobPayment — DELETE платежа не проверен' });
      }
    } finally {
      if (changed || !owner.isClosed()) {
        try {
          await openTeam(owner);
          await setMemberRole(owner, DISPATCHER_NAME, ROLE_DISPATCHER);
        } catch (e) {
          console.warn(`ВЕРНУТЬ РОЛЬ ВРУЧНУЮ: ${DISPATCHER_NAME} → ${ROLE_DISPATCHER} на /Team (компания test): ${String(e).slice(0, 200)}`);
        }
      }
    }
  });

  test('Admin-dispatcher has Delete in invoice Actions again after the role is restored #04d338 @desktop', async ({ asUser }) => {
    const dispatcher = await asUser('dispatcher');
    await prepare(dispatcher);
    await dispatcher.goto('/dashboard');
    await expectHeaderRole(dispatcher, DISPATCHER_NAME, ROLE_DISPATCHER);
    await openFirstInvoiceActions(dispatcher);
    // Только смотрим пункт меню, не нажимаем (источник: реджект №2 «у диспетчера Delete есть»)
    await expect(dispatcher.getByRole('menuitem', { name: /Delete/i })).toBeVisible();
    await dispatcher.keyboard.press('Escape');
  });
});
